mapper.select:
/*selectBuyerMpStStockAdjustList*/
SELECT X.BUYER , X.BYCA_COMORG_CODE , X.ITEM_NO , X.DESCRIPTION , X.SPECIFICATION , X.MAKER_CODE , X.MAKER_NAME , X.UNIT_MEASURE , X.TOT_QTY , X.TARGET_PRICE , X.CONTRACT_NO , X.CONTRACT_SEQ FROM ( SELECT A.BUYER , B.BUYER AS BYCA_COMORG_CODE , A.ITEM_NO , B.DESCRIPTION , B.SPECIFICATION , B.MAKER_CODE , B.MAKER_NAME , B.UNIT_MEASURE , A.TOT_QTY , B.TARGET_PRICE , B.CONTRACT_NO , B.CONTRACT_SEQ , ROW_NUMBER() OVER(PARTITION BY B.BUYER_ITEM_NO ORDER BY B.BUYER, B.CONTRACT_NO DESC, B.CONTRACT_SEQ DESC) AS MAX_CONT , A.CHANGE_DATE FROM BUYER_STOCK A /* 구매사 재고 관리 테이블 */ , ICOMCQDT B /* 구매사별 계약서 가격정보 */ , ICOMCMPY C /* 회원사정보 */ WHERE 1=1 AND A.BUYER = C.COM_CODE AND C.BYCA_COMORG_CODE = B.BUYER AND A.ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER = #{st_com_code} AND A.STATUS <> 'D' AND B.STATUS <> 'D'
AND A.ITEM_NO LIKE '%' || #{st_buyer_item_no} || '%'
AND B.DESCRIPTION LIKE '%' || #{st_description} || '%'
AND B.SPECIFICATION LIKE '%' || #{st_specification} || '%'
) X WHERE X.MAX_CONT = 1 /* 계약데이터는 마지막 계약을 기준으로 한다 */ ORDER BY X.CHANGE_DATE DESC
